mapper.select:
SELECT n.notice_id ,n.title, m.nickname writer, n.content, n.views, n.created_at, n.updated_at
FROM notice n inner join member m on n.member_id = m.member_id
WHERE notice_id = #{noticeId}

mapper.update:
UPDATE notice
SET title = #{notice.title}, content = #{notice.content}, updated_at = now()
WHERE notice_id = #{noticeId}
